proof={'status':'PASS actual frozen Metal bake; source/encoded/native checks remain separate','packetSha256':H(a.packet.read_bytes()),'preflightSha256':H((D/'cpu-preflight/preflight.json').read_bytes()),'started':start,'closed':stamp(),'seconds':time.time()-started,'actualDevice':r['device'],'resolution':r['resolution'],'samples':r['samples'],'staticPointLights':len(r['staticPracticalLights']),'illumination':r['illumination'],'atlasSurfaceArea':r['atlasSurfaceArea'],'allInputPinsStillExact':True,'runtimePointLightsExcluded':True,'outputs':{f.name:{'bytes':f.stat().st_size,'sha256':H(f.read_bytes())}for f in out.iterdir()if f.is_file()},'runnerSha256':H(Path(__file__).read_bytes())};(D/'actual-bake-completion.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps({'status':proof['status'],'seconds':proof['seconds'],'mean':r['illumination']['mean'],'maximum':r['illumination']['maximum'],'atlasArea':r['atlasSurfaceArea']}),flush=True)
